                    "userId": {
                      "type": "string",
                      "description": "A user identifier value that uniquely identifies a given User at the LFI."
                    }
                  },
                  "required": [
                    "userId"
                  ],
                  "description": "Properties of the requested challenge. Only the LFI user identifier is required.\n\nThe type of challenge is selected by the LFI, based on their internal implementation.\nIt must, however, be on the basis of a code that can be submitted by API Hub services\nfor verification."
                }
              },
              "required": [
                "data"
              ]
            }
          }
        },
        "description": "Request a new user challenge. Data will contain properties of User held at API Hub"
      }
    }
  },
  "security": [
    {},
    {
      "OzoneConnectApiKey": []
    },
    {
      "OzoneConnectClientCredentials": [
